import { _decorator, Component, Node, Button, find, Label, BlockInputEvents } from 'cc';
import { SharedBtnCounts } from './SharedBtnCounts';
import { HomePopupMask } from './HomePopupMask';
import { PetInfoBar } from './PetInfoBar';
import { CheckInPanel } from './CheckInPanel';
import { registerCarePanelClose } from './CarePanelBridge';

const { ccclass, property } = _decorator;

/**
 * 「照顾」弹层：展示喂食/玩耍/梳毛（复用 Canvas/btn 下三个按钮），可选展示签到领取区。
 * 挂在 Canvas/ad 或任意入口节点；由 AdButton 等调用 open()。
 */
@ccclass('CarePanel')
export class CarePanel extends Component {

    public static instance: CarePanel | null = null;

    @property({ tooltip: '三个道具按钮的父节点，默认 Canvas/btn' })
    itemsRoot: Node | null = null;

    @property({ tooltip: '签到区块（Check-in 节点），有待领取时才显示' })
    checkInNode: Node | null = null;

    @property(Button)
    closeButton: Button | null = null;

    @property(HomePopupMask)
    popupMask: HomePopupMask | null = null;

    @property({ tooltip: '签到已领时可选提示 Label' })
    checkInDoneLabel: Label | null = null;

    onLoad() {
        registerCarePanelClose(() => this.close());
        if (!this.itemsRoot) this.itemsRoot = find('Canvas/btn');
        if (!this.checkInNode) this.checkInNode = find('Canvas/Check-in');
        if (!this.popupMask) this.popupMask = find('Canvas/mask')?.getComponent(HomePopupMask) ?? null;
        if (!this.closeButton) {
            const close = this.node.getChildByName('close') ?? this.node.getChildByName('Close');
            if (close) this.closeButton = close.getComponent(Button);
        }
        if (this.closeButton) {
            this.closeButton.node.on(Button.EventType.CLICK, this.close, this);
        }
        if (this.itemsRoot) this.itemsRoot.active = false;
        if (this.checkInNode) this.checkInNode.active = false;
        this.popupMask?.setCloseCareCallback(() => this.close());
    }

    onEnable() {
        CarePanel.instance = this;
    }

    onDisable() {
        if (CarePanel.instance === this) CarePanel.instance = null;
    }

    onDestroy() {
        registerCarePanelClose(null);
        if (this.closeButton?.node?.isValid) {
            this.closeButton.node.off(Button.EventType.CLICK, this.close, this);
        }
        this.popupMask?.setCloseCareCallback(null);
    }

    /** 打开照顾弹层（道具 + 有待领时显示签到） */
    public open(): void {
        SharedBtnCounts.init();
        this._ensureBlockInput();

        if (this.itemsRoot) {
            this.itemsRoot.active = true;
        }
        SharedBtnCounts.onChangeCallback?.();

        const hasClaim = SharedBtnCounts.hasPendingClaim();
        if (this.checkInNode) {
            this.checkInNode.active = hasClaim;
            if (hasClaim) {
                const checkIn = this.checkInNode.getComponent(CheckInPanel);
                checkIn?.refreshForCarePanel();
            }
        }
        if (this.checkInDoneLabel) {
            this.checkInDoneLabel.node.active = !hasClaim;
        }

        this.popupMask?.setCareShowing(true);
        PetInfoBar.setGlobalVisible(false);
    }

    public close(): void {
        if (this.itemsRoot) this.itemsRoot.active = false;
        if (this.checkInNode) this.checkInNode.active = false;
        if (this.checkInDoneLabel) this.checkInDoneLabel.node.active = false;
        this.popupMask?.setCareShowing(false);
        PetInfoBar.setGlobalVisible(true);
    }

    private _ensureBlockInput() {
        const target = this.popupMask?.maskNode || this.popupMask?.node;
        if (target && !target.getComponent(BlockInputEvents)) {
            target.addComponent(BlockInputEvents);
        }
    }
}
